<?php foreach($transactions as $index=>$f):$hasReceipt=(bool)fuel_receipt_path($f['receipt_filename']); ?>
<details class="fuel-refill" id="record-<?= e($f['id']) ?>" <?= $index===0?'open':'' ?>>
<summary><span class="fuel-refill-reference"><strong><?= e($f['id']) ?></strong><span><?= e(fuel_datetime($f['transaction_date'])) ?></span></span><span class="fuel-refill-amount"><?= money($f['total_cost']) ?><?= fuel_badge($f['verification_status']) ?></span></summary>
<div class="fuel-refill-body"><div class="fuel-refill-columns"><section><h4>Refueling Details</h4><dl class="fuel-detail-grid fuel-detail-grid--two"><?php fuel_field('Refueling date',fuel_datetime($f['transaction_date']));fuel_field('Fuel type',$f['fuel_type']);fuel_field('Quantity purchased',fuel_number($f['liters']).' L');fuel_field('Unit price',fuel_unit_price($f['price_per_liter']).' / L');fuel_field('Total amount',money($f['total_cost']));fuel_field('Odometer',$f['odometer']===null?null:number_format((int)$f['odometer']).' km');fuel_field('Fuel station',$f['station']);fuel_field('Authorization',$f['authorization_id']?'#'.(int)$f['authorization_id']:null);fuel_field('Recorded vehicle',$f['plate_number']);fuel_field('Recorded driver',$f['driver_name']); ?></dl></section>
<section class="fuel-receipt-section"><h4>Receipt &amp; Submission</h4><?php if($hasReceipt): ?><button class="fuel-receipt-tile" type="button" data-fuel-receipt="<?= e($f['id']) ?>" aria-label="View receipt <?= e($f['id']) ?>"><?php if(in_array($f['receipt_mime']??'',['image/png','image/jpeg'],true)): ?><img loading="lazy" src="<?= BASE_URL ?>/actions/fuel-receipt.php?id=<?= rawurlencode($f['id']) ?>" alt="Uploaded receipt <?= e($f['id']) ?>"><?php else: ?><i class="bi bi-file-earmark-pdf" aria-hidden="true"></i><?php endif; ?><span>View receipt <i class="bi bi-box-arrow-up-right" aria-hidden="true"></i></span></button><?php else: ?><div class="fuel-no-receipt"><i class="bi bi-receipt" aria-hidden="true"></i>No receipt uploaded</div><?php endif; ?>
<dl class="fuel-detail-grid fuel-detail-grid--two"><?php fuel_field('Receipt number',$f['receipt_no']);fuel_field('Submitted by',$f['submitter_name']??null); ?></dl></section></div>
<section class="fuel-verification"><h4>Verification</h4><dl class="fuel-detail-grid fuel-detail-grid--two"><?php fuel_field('Dispatcher confirmation',$f['confirmed_at']?($f['confirmer_name']??'—').' · '.fuel_datetime($f['confirmed_at']):'Not confirmed');fuel_field('Admin verification',$f['verified_at']?($f['verifier_name']??'—').' · '.fuel_datetime($f['verified_at']):'Not verified'); ?></dl><?php if($f['review_reason']): ?><div class="fuel-review-note"><strong>Review reason</strong><p><?= e($f['review_reason']) ?></p></div><?php endif; ?>
<?php if((has_role('dispatcher')&&$f['verification_status']==='Submitted')||(has_role('fleet_admin')&&$f['verification_status']==='Pending Verification')): ?>
<?php require ROOT_PATH.'/includes/fuel-review-ui.php'; ?>
<?php elseif($f['verification_status']==='Returned'&&has_role(['driver','dispatcher','fleet_admin'])): ?><button type="button" class="tc-btn tc-btn-secondary tc-btn-sm mt-1" data-fuel-submit-authorization="<?= (int)$f['authorization_id'] ?>">Correct Submission</button><?php endif; ?>

</section></div></details>
<?php endforeach;if(!$transactions): ?><p class="fuel-muted-note">No refueling transactions for this trip.</p><?php endif; ?>
